require_once 'functions.php';require_admin();$pageTitle='Riwayat Pembelian';$active='purchases';
$rows=$pdo->query("SELECT p.*,u.full_name, (SELECT COUNT(*) FROM purchases p2 WHERE p2.user_id=p.user_id AND (p2.purchase_date<p.purchase_date OR (p2.purchase_date=p.purchase_date AND p2.id<=p.id))) AS seq FROM purchases p JOIN users u ON u.id=p.user_id ORDER BY p.purchase_date DESC,p.id DESC")->fetchAll();
