<div class="section-head"><div><p class="eyebrow">TRANSAKSI MEMBER</p><h3>Riwayat Pembelian</h3><p class="muted small">Urutan reward dihitung per member berdasarkan tanggal transaksi.</p></div><a class="btn primary" href="purchase_form.php">＋ Catat Pembelian</a></div>
<div class="table-wrap"><table><thead><tr><th>Nama Member</th><th>Tanggal</th><th>Ukuran</th><th>Reward</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):$free=((int)$r['seq']%5===0); ?><tr><td><b><?=e($r['full_name'])?></b></td><td><?=e($r['purchase_date'])?></td><td><?=e(format_ml($r['ml']))?> ml</td><td><?=$free?'<span class="pill gold-pill">GRATIS</span>':'<span class="pill">Pembelian '.(((int)$r['seq']-1)%5+1).'</span>'?></td><td class="actions"><a href="purchase_form.php?id=<?=$r['id']?>">Edit</a><form method="post" action="purchase_delete.php" onsubmit="return confirm('Hapus transaksi ini?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link-danger">Hapus</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">Belum ada transaksi.</td></tr><?php endif; ?></tbody></table></div><?php require 'footer.php'; ?>
